/**
 * Standalone Offline ZIP Generator (PKZIP Store Format)
 * 100% Self-Contained, No External Network Requests
 */
class JSZip {
    constructor() {
        this.files = {};
    }

    file(name, data) {
        this.files[name] = data;
        return this;
    }

    async generateAsync({ type = 'blob' } = {}) {
        const fileEntries = [];
        let offset = 0;

        for (const [name, content] of Object.entries(this.files)) {
            let buffer;
            if (content instanceof Uint8Array) {
                buffer = content;
            } else if (content instanceof Blob) {
                buffer = new Uint8Array(await content.arrayBuffer());
            } else if (typeof content === 'string') {
                buffer = new TextEncoder().encode(content);
            } else {
                buffer = new Uint8Array(content);
            }

            const nameBytes = new TextEncoder().encode(name);
            const crc32 = JSZip.crc32(buffer);

            // Local File Header (30 bytes + filename)
            const header = new Uint8Array(30 + nameBytes.length);
            const view = new DataView(header.buffer);
            view.setUint32(0, 0x04034b50, true); // Signature
            view.setUint16(4, 20, true);         // Version needed
            view.setUint16(6, 0, true);          // General purpose bit flag
            view.setUint16(8, 0, true);          // Compression method (0 = Store)
            view.setUint16(10, 0, true);         // Time
            view.setUint16(12, 0, true);         // Date
            view.setUint32(14, crc32, true);     // CRC-32
            view.setUint32(18, buffer.length, true); // Compressed size
            view.setUint32(22, buffer.length, true); // Uncompressed size
            view.setUint16(26, nameBytes.length, true);
            view.setUint16(28, 0, true);
            header.set(nameBytes, 30);

            fileEntries.push({
                nameBytes,
                crc32,
                buffer,
                header,
                offset,
                length: buffer.length
            });

            offset += header.length + buffer.length;
        }

        // Central Directory Headers
        const cdEntries = [];
        let cdSize = 0;

        for (const entry of fileEntries) {
            const cdHeader = new Uint8Array(46 + entry.nameBytes.length);
            const view = new DataView(cdHeader.buffer);
            view.setUint32(0, 0x02014b50, true); // Signature
            view.setUint16(4, 20, true);
            view.setUint16(6, 20, true);
            view.setUint16(8, 0, true);
            view.setUint16(10, 0, true);
            view.setUint16(12, 0, true);
            view.setUint16(14, 0, true);
            view.setUint32(16, entry.crc32, true);
            view.setUint32(20, entry.length, true);
            view.setUint32(24, entry.length, true);
            view.setUint16(28, entry.nameBytes.length, true);
            view.setUint16(30, 0, true);
            view.setUint16(32, 0, true);
            view.setUint16(34, 0, true);
            view.setUint16(36, 0, true);
            view.setUint32(38, 32, true);
            view.setUint32(42, entry.offset, true);
            cdHeader.set(entry.nameBytes, 46);

            cdEntries.push(cdHeader);
            cdSize += cdHeader.length;
        }

        // End of Central Directory Record (22 bytes)
        const eocd = new Uint8Array(22);
        const eocdView = new DataView(eocd.buffer);
        eocdView.setUint32(0, 0x06054b50, true);
        eocdView.setUint16(4, 0, true);
        eocdView.setUint16(6, 0, true);
        eocdView.setUint16(8, fileEntries.length, true);
        eocdView.setUint16(10, fileEntries.length, true);
        eocdView.setUint32(12, cdSize, true);
        eocdView.setUint32(16, offset, true);
        eocdView.setUint16(20, 0, true);

        // Combine into single Uint8Array
        const totalSize = offset + cdSize + eocd.length;
        const zipBuffer = new Uint8Array(totalSize);
        let pos = 0;

        for (const entry of fileEntries) {
            zipBuffer.set(entry.header, pos);
            pos += entry.header.length;
            zipBuffer.set(entry.buffer, pos);
            pos += entry.buffer.length;
        }

        for (const cdHeader of cdEntries) {
            zipBuffer.set(cdHeader, pos);
            pos += cdHeader.length;
        }

        zipBuffer.set(eocd, pos);

        if (type === 'uint8array') return zipBuffer;
        return new Blob([zipBuffer], { type: 'application/zip' });
    }

    static crc32(buf) {
        let crc = -1;
        for (let i = 0; i < buf.length; i++) {
            let byte = buf[i];
            crc = (crc >>> 8) ^ JSZip.crcTable[(crc ^ byte) & 0xff];
        }
        return (crc ^ -1) >>> 0;
    }
}

// Pre-calculate CRC32 table
JSZip.crcTable = (() => {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let k = 0; k < 8; k++) {
            c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
        }
        table[i] = c;
    }
    return table;
})();

window.JSZip = JSZip;
